async def sessions_list():
    """HTML session table for the Efficiency tab (htmx target)."""

    sessions = _list_recent_sessions()
    if not sessions:
        return HTMLResponse(
            '<div class="state-msg"><div class="ico">📭</div>'
            "<h3>No sessions found</h3>"
            "<p>No Hermes session data available. Run an agent, then check back.</p></div>"
        )

    rows = []
    for sid, ts in sessions:
        turns = _parse_session(sid)
        if not turns:
            continue
        eff = compute_efficiency(turns, session_id=sid)
        arch = classify_archetype(turns)
        outcome = compute_effectiveness(turns)
        # Per-archetype baseline line
        baseline = compute_baseline(sid, arch["archetype"])
        baseline_line = ""
        if baseline.get("baseline") is not None and eff["score"] is not None:
            delta = eff["score"] - baseline["baseline"]
            cmp = f"{delta:+d}" if delta != 0 else "on par with"
            baseline_line = f"Score {eff['score']} vs your usual {baseline['baseline']} for {arch['archetype']} ({baseline['peer_count']} peers) — {cmp}"
        score = eff["score"]
        score_cls = "bad" if (score is not None and score < 50) else "warn" if (score is not None and score < 80) else "good"
        rows.append(f"""<tr class="sess-row" onclick="toggleSessionDetail('{sid}')">
    <td class="mono">{_esc(sid[:19])}</td>
    <td><span class="chip {_esc(arch['archetype'])}">{_esc(arch['archetype'])}</span></td>
    <td><span class="score {score_cls}">{score if score is not None else '—'}</span></td>
    <td><span class="chip {'ok' if outcome['verdict'] in ('succeeded','likely ok') else 'bad'}">{_esc(outcome['verdict'])}</span></td>
</tr>
<div id="{sid}-detail" class="sess-detail" style="display:none">
    {_render_efficiency_card(turns, eff, arch, outcome, sid=sid, baseline_line=baseline_line)}
</div>""")

    if not rows:
        return HTMLResponse(
            '<div class="state-msg"><div class="ico">📭</div>'
            "<h3>No sessions found</h3>"
            "<p>Could not parse any sessions.</p></div>"
        )

    return HTMLResponse(f"""<div class="sec-h">Recent Sessions</div>
<table class="tbl sess-tbl">
  <tr><th>Session</th><th>Archetype</th><th>Efficiency</th><th>Outcome</th></tr>
  {''.join(rows)}
</table>
<script>
function toggleSessionDetail(id) {{
  var el = document.getElementById(id + '-detail');
  if (el) el.style.display = el.style.display === 'none' ? 'block' : 'none';
}}
function optimizeSession(sid, btn) {{
  var result = document.getElementById('opt-' + sid);
  btn.disabled = true;
  btn.textContent = 'Optimizing…';
  fetch('/api/efficiency/optimize/apply/' + sid, {{method: 'POST', headers: {{'X-ObserveCo-Token': window.__OBSERVECO_TOKEN || ''}} }})
    .then(function(r) {{ return r.json(); }})
    .then(function(data) {{
      result.style.display = 'block';
      if (data.status === 'applied') {{
        result.innerHTML = '<span class="opt-ok">✓ Written to AGENTS.md — ~' + (data.reclaimable_tokens||0).toLocaleString() + ' tokens reclaimable per run</span>';
        btn.textContent = 'Optimized ✓';
      }} else if (data.status === 'noop') {{
        result.innerHTML = '<span class="opt-ok">' + (data.message||'Nothing to optimize') + '</span>';
        btn.textContent = 'No waste';
      }} else {{
        result.innerHTML = '<span class="opt-err">Error: ' + (data.detail||'unknown') + '</span>';
        btn.textContent = 'Retry';
        btn.disabled = false;
      }}
    }})
    .catch(function(e) {{
      result.style.display = 'block';
      result.innerHTML = '<span class="opt-err">Request failed</span>';
      btn.textContent = 'Retry';
      btn.disabled = false;
    }});
}}
</script>""")

# --- helper ---

def _render_efficiency_card(turns, eff, arch, outcome, sid: str = "", baseline_line: str = "") -> str:
    """Expandable per-session efficiency card."""
    metrics_html = []
    for m in eff["metrics"]:
        if m["status"] == "noop":
            continue
        label = m["id"].replace("-", " ").title()
        detail = ""
        if isinstance(m.get("value"), dict):
            if "files" in m["value"] and isinstance(m["value"]["files"], dict):
                files = list(m["value"]["files"].keys())[:3]
                detail = ", ".join(files)
                if len(m["value"]["files"]) > 3:
                    detail += f" +{len(m['value']['files']) - 3} more"
            elif "reclaimable_tokens" in m["value"]:
                detail = f"~{m['value']['reclaimable_tokens']:,} reclaimable"
        metrics_html.append(f"""<div class="metric-row {m['status']}">
    <span class="m-dot">●</span>
    <span class="m-label">{label}</span>
    <span class="m-detail">{_esc(detail)}</span>
</div>""")

    optimize_html = ""
    if sid and eff.get("_reclaimable", 0) > 0:
        optimize_html = f"""<button class="btn-opt" onclick="optimizeSession('{sid}', this)">Optimize future runs →</button>
<div class="opt-result" id="opt-{sid}" style="display:none"></div>"""

    baseline_html = f'<div class="baseline-line">{_esc(baseline_line)}</div>' if baseline_line else ""

    return f"""<div class="efficiency-card">
    <div class="eff-score">Efficiency {eff['score']} · Outcome {outcome['score']} ({_esc(outcome['verdict'])})</div>
    {''.join(metrics_html)}
    {baseline_html}
    {optimize_html}
</div>"""

        border_cls = " restart-card-border crash" if crash > 0 else ""

        cards.append(f"""<div class="agent-card{border_cls}" id="rq-card-{agent_name}">
    <div class="restart-card-header">
        <span class="restart-card-name">{_html_escape(agent_name)}</span>
        <span class="restart-card-badge" style="color:{far_color};">{far_icon} {far_text}</span>
        </div>
    </div>
    <div class="restart-card-detail">
        <div class="restart-card-stat"><span class="restart-card-stat-key">Restarts:</span> <span class="restart-card-stat-val">{total}</span></div>
        <div class="restart-card-stat"><span class="restart-card-stat-key green">KeepAlive:</span> <span class="restart-card-stat-val">{healthy}</span></div>
        <div class="restart-card-stat"><span class="restart-card-stat-key amber">TOCTOU:</span> <span class="restart-card-stat-val">{toctou}</span></div>
        <div class="restart-card-stat"><span class="restart-card-stat-key red">Crashes:</span> <span class="restart-card-stat-val">{crash}</span></div>
    </div>
    <div class="restart-bar-section">
        <div class="restart-bar-header">
            <span>Restart quality breakdown</span>
        </div>
        <div class="restart-bar">
            {f'<div class="restart-bar-seg green" style="width:{green_pct:.0f}%;">{healthy}</div>' if healthy > 0 else ''}
            {f'<div class="restart-bar-seg amber" style="width:{amber_pct:.0f}%;">{toctou}</div>' if toctou > 0 else ''}
            {f'<div class="restart-bar-seg red" style="width:{red_pct:.0f}%;">{crash}</div>' if crash > 0 else ''}
        </div>
    </div>
    <div class="restart-toggle" onclick="toggleRestartDetail('{agent_name}')">▶ View restart timeline</div>
    <div class="restart-detail-panel" id="rq-detail-{agent_name}">
        <div class="restart-detail-content" id="rq-detail-content-{agent_name}">Loading...</div>
    </div>
</div>""")

    cards_html = "\n".join(cards)

    return HTMLResponse(f"""<div class="restart-quality-tab">
    {fleet_html}
    {legend_html}
    <div class="agent-restart-cards">
        {cards_html}
    </div>
</div>
<script>
function toggleRestartDetail(agentName) {{
    var el = document.getElementById('rq-detail-' + agentName);
    if (!el) return;
    var open = el.style.display !== 'none';
    el.style.display = open ? 'none' : 'block';
    if (!open) {{
        var content = document.getElementById('rq-detail-content-' + agentName);
        if (content) {{
            content.innerHTML = 'Loading...';
            fetch('/api/restart-quality/' + encodeURIComponent(agentName))
                .then(r => r.text())
                .then(html => {{ content.innerHTML = html; }});
        }}
    }}
}}
</script>""")


@app.get("/api/restart-quality/{agent_name}", response_class=HTMLResponse)
async def api_restart_quality_detail(agent_name: str):
    """Restart timeline detail for a single agent."""
    name = agent_name
    restarts = db.get_recent_restarts(agent_name=name, limit=50)
    if not restarts:
        return HTMLResponse('<div class="restart-empty">No restart data for this agent.</div>')

    items = []
    for r in restarts:
        ts_str = _fmt_ts(r["timestamp"])
        rtype = r["restart_type"]
        duration = r.get("duration_ms", 0)
        snippet = r.get("crash_log_snippet", "")[:120]
        evidence = r.get("evidence", "")

        type_colors = {
            "healthy": ("#22c55e", "Launchd KeepAlive"),
            "toctou": ("#eab308", "TOCTOU race"),
            "crash": ("#ef4444", "Crash"),
        }
        color, label = type_colors.get(rtype, ("#64748b", "Unknown"))

        duration_str = f"{duration}ms recovery" if duration else ""
        snippet_html = f'<div class="restart-snippet">{_html_escape(snippet)}</div>' if snippet else ""

        items.append(f"""<div class="restart-timeline-row">
    <span class="restart-timeline-dot" style="background:{color};left:0;"></span>
    <div class="restart-timeline-header">
        <span class="restart-timeline-ts">{ts_str}</span>
        <span class="restart-timeline-label" style="color:{color};">{label}</span>
        {f'<span class="restart-timeline-duration">{duration_str}</span>' if duration_str else ''}
    </div>
    {snippet_html}
    {f'<div class="restart-evidence">{_html_escape(evidence)}</div>' if evidence else ''}
</div>""")

    return HTMLResponse(f"""<div class="restart-timeline">
    <div class="restart-timeline-rail">
        {''.join(items)}
    </div>
</div>""")


@app.post("/api/restart-quality/scan", response_class=JSONResponse)
async def api_restart_quality_scan():
    """Run a full pulse scan to collect restart data — Pro only."""
    from observeco import license as lic
    if not lic.require_pro():
        return JSONResponse({"ok": False, "error": "Pro license required"}, status_code=403)
    try:
        from observeco.pulse.check import run_check
        run_check(watch=False)
        return JSONResponse({"ok": True, "message": "Pulse scan complete"})
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)})


